"""Contact sheet rows for substitute teachers."""

from typing import Iterable, List

from rosterkit.models import Student
from rosterkit.errors import ProjectError

# ---
def contact_rows(students: Iterable[Student]) -> List[str]:
    """Aligned contact rows sorted by name."""
    ordered = sorted(
        students, key=lambda item: item.display_name
    )
    _check_contacts(ordered)
    return _format_rows(ordered)

def _check_contacts(ordered: List[Student]) -> None:
    if not ordered:
        raise ProjectError("no students to list")
    for item in ordered:
        if not item.email:
            name = item.display_name
            raise ProjectError(f"no email for {name}")

def _format_rows(ordered: List[Student]) -> List[str]:
    names = _pad([item.display_name for item in ordered])
    labels = _pad([item.section for item in ordered])
    return [
        f"{name}  {label}  {item.email}"
        for name, label, item in zip(names, labels, ordered)
    ]

def _pad(values: List[str]) -> List[str]:
    width = max(len(value) for value in values)
    return [value.ljust(width) for value in values]
